style.css:
@-moz-document domain("digitalbanking.purduefed.com") {
html {
    filter: invert(1) hue-rotate(180deg);
    background: #fff;
  }

  /* The top nav bar is already dark/black in the light theme,
     so inverting it would turn it white. Un-invert it back to original. */
  .navbar-container,
  .navbar-content {
    filter: invert(1) hue-rotate(180deg);
  }

  /* Un-invert real images, video, icons and anything with a background
     image (photos, logos, the promo banner, sprite icons) so colors/photos
     stay natural instead of looking like photo negatives. */
  img,
  picture,
  video,
  canvas,
  svg,
  iframe,
  embed,
  object,
  [style*="background-image"],
  .icon,
  [class*="icon-"] {
    filter: invert(1) hue-rotate(180deg);
  }

  /* Let native form controls (checkboxes, date pickers, scrollbars) and
     the browser's own dark chrome match. */
  html {
    color-scheme: dark;
  }

  /* Webkit scrollbar to match dark background */
  ::-webkit-scrollbar {
    background: #1a1a1a;
  }
  ::-webkit-scrollbar-thumb {
    background: #444;
  }
}
